#!/usr/bin/env python3
import sys


def solve(N: int, M: int, P: "List[List[int]]"):
    fallen = -1
    count = 0
    P.sort(key=lambda p: p[1] * N - p[0])
    for p in P:
        if fallen==p[1]-1:
            continue
        if p[0] <= fallen:
            continue
        fallen = p[1]-1
        count += 1
    print(count)
    return


# Generated by 1.1.4 https://github.com/kyuridenamida/atcoder-tools  (tips: You use the default template now. You can remove this line by using your custom template)
def main():
    def iterate_tokens():
        for line in sys.stdin:
            for word in line.split():
                yield word
    tokens = iterate_tokens()
    N = int(next(tokens))  # type: int
    M = int(next(tokens))  # type: int
    P = [[int(), int()] for _ in range(M)]   # type: "List[List[int]]" 
    for i in range(M):
        P[i] = [int(next(tokens)), int(next(tokens))]
    solve(N, M, P)

if __name__ == '__main__':
    main()
